import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { 
  Card, 
  Button, 
  Table, 
  DatePicker, 
  Alert, 
  Space, 
  Title, 
  Text 
} from '../components/BasicUI';

const Home = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [analyzing, setAnalyzing] = useState({});

  const fetchGames = async (date) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(`/api/games/today?date=${date}`);
      setGames(response.data.data || []);
    } catch (err) {
      setError('Error al cargar los partidos: ' + (err.response?.data?.message || err.message));
    } finally {
      setLoading(false);
    }
  };

  const analyzeGame = async (gameId) => {
    setAnalyzing(prev => ({ ...prev, [gameId]: true }));
    try {
      await axios.post(`/api/games/analyze/${gameId}`);
      // Recargar los partidos después del análisis
      fetchGames(selectedDate);
    } catch (err) {
      setError('Error al analizar el partido: ' + (err.response?.data?.message || err.message));
    } finally {
      setAnalyzing(prev => ({ ...prev, [gameId]: false }));
    }
  };

  const handleDateChange = (e) => {
    const date = e.target.value;
    setSelectedDate(date);
    fetchGames(date);
  };

  useEffect(() => {
    fetchGames(selectedDate);
  }, []);

  const columns = [
    {
      title: 'Hora',
      dataIndex: 'game_time',
      render: (time) => new Date(time).toLocaleTimeString('es-ES', { 
        hour: '2-digit', 
        minute: '2-digit' 
      })
    },
    {
      title: 'Visitante',
      dataIndex: 'away_team_name',
    },
    {
      title: 'Local',
      dataIndex: 'home_team_name',
    },
    {
      title: 'Abridor Visitante',
      dataIndex: 'away_probable_pitcher',
      render: (pitcher) => pitcher || 'TBD'
    },
    {
      title: 'Abridor Local',
      dataIndex: 'home_probable_pitcher',
      render: (pitcher) => pitcher || 'TBD'
    },
    {
      title: 'Estado',
      dataIndex: 'status',
      render: (status) => {
        if (status === 'analyzed') return 'Analizado';
        if (status === 'pending') return 'Pendiente';
        return status;
      }
    },
    {
      title: 'Acciones',
      dataIndex: 'id',
      render: (gameId, record) => (
        <Button
          type="primary"
          onClick={() => analyzeGame(gameId)}
          loading={analyzing[gameId]}
          disabled={record.status === 'analyzed'}
        >
          {record.status === 'analyzed' ? 'Analizado' : 'Analizar'}
        </Button>
      )
    }
  ];

  return (
    <div className="home-page">
      <Title level={1}>Partidos del Día</Title>
      
      <Space direction="vertical" size="large">
        <Card title="Filtros">
          <Space>
            <Text>Fecha:</Text>
            <DatePicker
              value={selectedDate}
              onChange={handleDateChange}
            />
            <Button onClick={() => fetchGames(selectedDate)} loading={loading}>
              Actualizar
            </Button>
          </Space>
        </Card>

        {error && (
          <Alert
            type="error"
            message="Error"
            description={error}
          />
        )}

        <Card title={`Partidos - ${new Date(selectedDate).toLocaleDateString('es-ES')}`}>
          <Table
            columns={columns}
            dataSource={games}
            loading={loading}
          />
        </Card>
      </Space>
    </div>
  );
};

export default Home;
